"use client";

import { useEffect, useState } from "react";

type User = { id: string; name: string; email: string; role: string; employer_status: string; company_name?: string; employer_reason?: string };

export default function AdminUsersPage() {
  const [users, setUsers] = useState<User[]>([]);
  const [error, setError] = useState("");

  async function load() {
    const response = await fetch("/api/admin/users");
    const data = await response.json();
    if (!response.ok) return setError(data.error ?? "Unable to load users");
    setUsers(data.users ?? []);
  }

  async function review(userId: string, status: "approved" | "rejected") {
    const response = await fetch("/api/admin/users", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ userId, status }) });
    if (!response.ok) {
      const data = await response.json();
      setError(data.error ?? "Unable to review application");
      return;
    }
    await load();
  }

  useEffect(() => { void load(); }, []);
  const pending = users.filter((user) => user.employer_status === "pending");

  return (
    <main className="min-h-screen bg-[#f5f7fb] p-6 text-slate-900 sm:p-10">
      <div className="mx-auto max-w-6xl">
        <a className="text-sm font-bold text-[#e15a3d]" href="/admin">← Dashboard</a>
        <h1 className="mt-6 text-4xl font-bold tracking-tight">Users and verification</h1>
        <p className="mt-2 text-sm text-slate-500">Approve employer access only after reviewing the submitted company details.</p>
        {error && <p className="mt-5 rounded-xl bg-rose-50 p-4 text-sm text-rose-700" role="alert">{error}</p>}
        <section className="mt-8 rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-100 p-5"><h2 className="font-bold">Pending employer applications ({pending.length})</h2></div>
          {pending.length === 0 ? <p className="p-6 text-sm text-slate-500">No applications need review.</p> : pending.map((user) => (
            <article className="grid gap-4 border-b border-slate-100 p-5 last:border-0 md:grid-cols-[1fr_2fr_auto] md:items-start" key={user.id}>
              <div><strong>{user.company_name}</strong><p className="mt-1 text-sm text-slate-500">{user.name} · {user.email}</p></div>
              <p className="text-sm leading-6 text-slate-600">{user.employer_reason}</p>
              <div className="flex gap-2"><button className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-bold text-white" onClick={() => void review(user.id, "approved")} type="button">Approve</button><button className="rounded-lg bg-rose-600 px-3 py-2 text-xs font-bold text-white" onClick={() => void review(user.id, "rejected")} type="button">Reject</button></div>
            </article>
          ))}
        </section>
        <section className="mt-8 rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-100 p-5"><h2 className="font-bold">All users ({users.length})</h2></div>
          <div className="divide-y divide-slate-100">{users.map((user) => <div className="flex flex-wrap justify-between gap-3 p-5 text-sm" key={user.id}><span><strong>{user.name}</strong> <span className="text-slate-500">{user.email}</span></span><span className="font-bold uppercase tracking-wider text-slate-400">{user.role} · {user.employer_status}</span></div>)}</div>
        </section>
      </div>
    </main>
  );
}
